"""GPU stages for a manifest generated by plan.py; no external shell commands."""
import argparse
import collections
import gc
import json
import os
from pathlib import Path
import time


def capture(job, paths, root):
    import torch
    from tools.rebuttal.core import load_model, side_of, seed_all, write_json
    from gr00t.quantization.dit_step_context import get_current_dit_step
    cfg = job['config']
    _, model, samples, infer = load_model(cfg, paths)
    targets = {n:m for n,m in model.named_modules() if isinstance(m, torch.nn.Linear) and side_of(n, cfg['model'])}
    if not any(side_of(n, cfg['model']) == 'head' for n in targets) or not any(side_of(n, cfg['model']) == 'backbone' for n in targets):
        raise RuntimeError('Target regexes must match both backbone and head')
    target_dir = root / job['output']
    target_dir.mkdir(parents=True, exist_ok=True)
    cache = {n:collections.defaultdict(list) for n in targets}
    counts = {n:collections.Counter() for n in targets}
    inventory = []
    for n,m in model.named_modules():
        if isinstance(m, torch.nn.Linear):
            inventory.append({'name':n, 'shape':list(m.weight.shape), 'dtype':str(m.weight.dtype),
                              'weight_bytes':m.weight.numel()*m.weight.element_size(), 'side':side_of(n,cfg['model'])})
    cap = cfg['token_cap']
    def hook(name):
        def run(mod, inputs):
            side = side_of(name, cfg['model'])
            t = get_current_dit_step()
            if side == 'head' and t is None:
                raise RuntimeError(f'Missing denoising context at {name}; refuse a zero scale table')
            key = int(t) if side == 'head' else -1
            x = inputs[0].detach().reshape(-1, inputs[0].shape[-1]).float()
            # Bound host RAM; deterministic subsampling under the per-sample seed.
            if x.shape[0] > cap:
                x = x[torch.randperm(x.shape[0], device=x.device)[:cap]]
            cache[name][key].append(x.cpu())
            counts[name][key] += len(x)
        return run
    handles = [m.register_forward_pre_hook(hook(n)) for n,m in targets.items()]
    try:
        with torch.inference_mode(), torch.autocast('cuda', dtype=torch.bfloat16):
            for i, obs in enumerate(samples):
                seed_all(cfg['cal_seed'] + i)
                infer(obs)
                print(f'capture {i+1}/{len(samples)}', flush=True)
    finally:
        for h in handles:
            h.remove()
    layers = []
    for i,(name, mod) in enumerate(targets.items()):
        side = side_of(name,cfg['model'])
        expected = set(range(cfg['steps'])) if side == 'head' else {-1}
        if set(cache[name]) != expected:
            raise RuntimeError(f'{name}: expected buckets {expected}, got {set(cache[name])}')
        data = {t:torch.cat(xs) for t,xs in cache[name].items()}
        file = f'layer_{i:04}.pt'
        torch.save({'weight':mod.weight.detach().cpu(), 'x':data, 'side':side, 'name':name}, target_dir/file)
        cache[name].clear()
        layers.append({'name':name,'file':file,'side':side,'tokens':dict(counts[name])})
    total_model_bytes = sum(p.numel()*p.element_size() for p in model.parameters())
    write_json(target_dir/'index.json', {'config':cfg,'layers':layers,'inventory':inventory,
                                        'parameter_bytes':total_model_bytes,'diagnostic_data':'calibration inputs; not held-out'})


def quantize_weight(weight, x, config, side):
    import torch
    if (side == 'head' and config['head_solver'] == 'rtn') or config['solver'] == 'rtn':
        qmax = 2**(config['wbits']-1)-1
        scale = weight.abs().amax(-1,keepdim=True).clamp_min(1e-8)/qmax
        return torch.round(weight/scale).clamp(-qmax,qmax)*scale
    from gr00t.quantization.gptq_layers import gptq_quantize_weight
    h = x.T @ x / len(x)
    return gptq_quantize_weight(weight,h,bits=config['wbits'],block_size=128,damp_percent=0.01)


def build(job, paths, root):
    import torch
    from tools.rebuttal.core import make_rotation, block_transform, write_json, tensor_bytes
    cfg = job['config']
    source = root / job['capture']
    index = json.loads((source/'index.json').read_text())
    records = {}
    diagnostics = []
    for entry in index['layers']:
        if cfg['scope'] != 'both' and cfg['scope'] != entry['side']:
            continue
        data = torch.load(source/entry['file'],map_location='cpu',weights_only=False)
        w = data['weight'].float().cuda()
        blocks, perm = make_rotation(w,cfg['rotation'],cfg['block'],permute=cfg['permute'])
        wr = block_transform(w,blocks,perm)
        xs = {t:block_transform(x.cuda(),blocks,perm) for t,x in data['x'].items()}
        allx = torch.cat(list(xs.values()))
        wq = quantize_weight(wr,allx,cfg,entry['side'])
        qmax = 2**(cfg['abits']-1)-1 if cfg['abits'] else 1
        if entry['side']=='head' and cfg['abits']:
            if cfg['scaling']=='perstep':
                scales = torch.stack([torch.quantile(xs[t].abs(),0.999,dim=0).clamp_min(1e-8)/qmax for t in range(cfg['steps'])])
            else:
                scales = (torch.quantile(allx.abs(),0.999,dim=0).clamp_min(1e-8)/qmax).unsqueeze(0)
        else:
            scales = torch.empty(0,w.shape[1],device=w.device)
        rec = {'side':entry['side'],'weight_q':wq.half().cpu(), 'blocks':blocks.cpu(),
               'perm':perm.cpu(), 'scales':scales.cpu()}
        records[entry['name']] = rec
        # Report weight-only, activation-only, and joint output errors on the SAME FP inputs.
        nums = {'weight_only':0.0,'activation_only':0.0,'joint':0.0,'rotation_roundoff':0.0}
        denom = 0.0
        for t,xr in xs.items():
            x = data['x'][t].cuda().float()
            y = x @ w.T
            if cfg['abits']:
                if entry['side']=='backbone':
                    scale = xr.abs().amax(-1,keepdim=True).clamp_min(1e-8)/qmax
                else:
                    scale = scales[t if cfg['scaling']=='perstep' else 0]
                xq = torch.round(xr/scale).clamp(-qmax,qmax)*scale
            else:
                xq = xr
            denom += y.square().sum().item()
            for key,yhat in [('weight_only',xr@wq.T),('activation_only',xq@wr.T),
                             ('joint',xq@wq.T),('rotation_roundoff',xr@wr.T)]:
                nums[key] += (yhat-y).square().sum().item()
        metrics = {k:v/max(denom,1e-30) for k,v in nums.items()}
        if metrics['rotation_roundoff']>1e-6:
            raise RuntimeError(f'Broken rotation equivalence in {entry["name"]}: {metrics}')
        # Row norms of W.T are input-channel norms under paper convention.
        norms0 = torch.linalg.vector_norm(w,dim=0)
        norms1 = torch.linalg.vector_norm(wr,dim=0)
        metrics.update(name=entry['name'],side=entry['side'],tokens=len(allx),
                       input_norm_ratio_before=(norms0.max()/norms0.min().clamp_min(1e-12)).item(),
                       input_norm_ratio_after=(norms1.max()/norms1.min().clamp_min(1e-12)).item())
        diagnostics.append(metrics)
        del w,wr,wq,xs,allx,blocks,perm,scales
        gc.collect()
        torch.cuda.empty_cache()
        print(f'build {len(records)} {entry["name"]} joint_nmse={metrics["joint"]:.6g}',flush=True)
    if not records:
        raise RuntimeError('Empty pack')
    target=root/job['output']
    target.parent.mkdir(parents=True,exist_ok=True)
    torch.save({'format':'rebuttal_reference_v1','config':cfg,'records':records},target.with_suffix('.tmp'))
    target.with_suffix('.tmp').replace(target)
    write_json(target.with_suffix('.diagnostics.json'),{'config':cfg,'layers':diagnostics,'data':'calibration inputs'})
    meta_bytes = sum(tensor_bytes({k:v for k,v in r.items() if k!='weight_q'}) for r in records.values())
    weight_bytes = sum(tensor_bytes(r['weight_q']) for r in records.values())
    inventory = index['inventory']
    target_names=set(records)
    fp_target = sum(r['weight_bytes'] for r in inventory if r['name'] in target_names)
    # Logical packed estimate ONLY, clearly separate from serialized and runtime tensors.
    logical_weights=sum((r['weight_q'].numel()*cfg['wbits']+7)//8 for r in records.values())
    write_json(target.with_suffix('.inventory.json'),{'config':cfg,'target_layers':len(records),
        'layers':inventory,'execution':'fake quant + floating-point GEMM; no native INT4 kernels',
        'serialized_pack_bytes':target.stat().st_size,'dequantized_weight_tensor_bytes':weight_bytes,
        'metadata_tensor_bytes':meta_bytes,'logical_packed_weight_bytes_estimate':logical_weights,
        'logical_estimate_excludes_weight_scale_and_packing_overhead':True,
        'unquantized_parameter_bytes':index['parameter_bytes']-fp_target,
        'parameter_bytes_before':index['parameter_bytes']})


def loaded(job, paths, root):
    import torch
    from tools.rebuttal.core import load_model
    from tools.rebuttal.runtime import install
    policy, model, samples, infer = load_model(job['config'], paths)
    names=[]
    if job.get('pack'):
        pack=torch.load(root/job['pack'],map_location='cpu',weights_only=False)
        if pack['config']!=job['config']:
            raise RuntimeError('Pack config mismatch')
        names=install(model,pack,job['config'])
        del pack
    model.eval()
    return policy,model,samples,infer,names


def evaluate(job, paths, root):
    import numpy as np
    import torch
    from libero.libero import benchmark
    from examples.Libero.eval.run_libero_eval import ExternalPolicy, get_max_steps
    from examples.Libero.eval.utils import get_libero_env, get_libero_dummy_action
    from tools.rebuttal.core import seed_all, write_json
    cfg=job['config']
    policy, model, _, _, names=loaded(job,paths,root)
    # Reuse repository observation/action conventions; bypass sockets only.
    class DirectPolicy(ExternalPolicy):
        def __init__(self):
            self.policy=policy
            self.policy_backend='groot_zmq' if cfg['model']=='groot' else 'openpi_ws'
            self.headless=True
            self.policy_output_format='gr00t_dict'
            self.response_action_key='action'
            self.resize_size=224
            self.replan_steps=5
            self.action_plan=collections.deque()
            self.action_keys=['x','y','z','roll','pitch','yaw','gripper']
    task_name='libero_10' if cfg['suite']=='long' else 'libero_'+cfg['suite']
    suite=benchmark.get_benchmark_dict()[task_name]()
    target=root/job['output']
    # Completed jobs are handled by done.json; failed partial runs restart exactly.
    episodes=[]
    adapter=DirectPolicy()
    max_steps=get_max_steps(task_name,'groot' if cfg['model']=='groot' else 'openpi')
    offset=cfg['eval_offset']
    for task_id in range(suite.n_tasks):
        task=suite.get_task(task_id)
        states=suite.get_task_init_states(task_id)
        if len(states)<offset+cfg['trials']:
            raise RuntimeError(f'Not enough initial states: task {task_id}')
        env,_=get_libero_env(task,resolution=256)
        try:
            for trial in range(cfg['trials']):
                episode_seed=cfg['eval_seed']+task_id*1000+trial
                seed_all(episode_seed)
                env.seed(episode_seed)
                env.reset()
                adapter.reset_episode()
                obs=env.set_init_state(states[offset+trial])
                done=False
                error=None
                try:
                    for t in range(max_steps+10):
                        if t<10:
                            obs,_,_,_=env.step(get_libero_dummy_action())
                            continue
                        with torch.inference_mode():
                            action=adapter.get_action(obs,task.language)
                        action=np.asarray(action)
                        if not np.isfinite(action).all():
                            raise FloatingPointError('Nonfinite policy action')
                        obs,_,done,_=env.step(action.tolist())
                        if done:
                            break
                except Exception as exc:
                    error=f'{type(exc).__name__}: {exc}'
                episodes.append({'task_id':task_id,'trial':trial,'init_index':offset+trial,
                                 'seed':episode_seed,'success':bool(done),'error':error})
                write_json(target,{'config':cfg,'episodes':episodes,'complete':False})
                if error:
                    raise RuntimeError(error)  # Never quietly count implementation errors as task failures.
                print(f'task={task_id} trial={trial} success={done}',flush=True)
        finally:
            env.close()
    write_json(target,{'config':cfg,'episodes':episodes,'complete':True,'target_layers':names,
                      'total_episodes':len(episodes),'total_successes':sum(x['success'] for x in episodes),
                      'execution':'reference fake-quant floating GEMM' if names else 'original floating model',
                      'timing_scope':'policy evaluation, no simulator wall-clock speed claim'})


def profile(job, paths, root):
    import statistics
    import torch
    from tools.rebuttal.core import write_json, seed_all
    policy,model,samples,infer,names=loaded(job,paths,root)
    # load_model normalizes GR00T samples for capture. Timings below cover full model.get_action,
    # including vision and denoising, but not external observation normalization or simulator.
    cfg=job['config']
    def call(i):
        seed_all(cfg['eval_seed']+i)
        with torch.inference_mode():
            infer(samples[i%len(samples)])
    for i in range(5):
        call(i)
    torch.cuda.synchronize()
    torch.cuda.reset_peak_memory_stats()
    times=[]
    for i in range(30):
        # RNG seeding outside timed region.
        seed_all(cfg['eval_seed']+i)
        torch.cuda.synchronize()
        start=time.perf_counter()
        with torch.inference_mode():
            infer(samples[i%len(samples)])
        torch.cuda.synchronize()
        times.append((time.perf_counter()-start)*1000)
    result={'config':cfg,'target_layers':names,'latency_ms':times,'median_ms':statistics.median(times),
            'mean_ms':statistics.mean(times),'peak_allocated_bytes':torch.cuda.max_memory_allocated(),
            'peak_reserved_bytes':torch.cuda.max_memory_reserved(),'gpu':torch.cuda.get_device_name(),
            'torch':torch.__version__,'parameter_dtypes':sorted({str(p.dtype) for p in model.parameters()}),'execution':'reference fake quant + BF16/FP32 GEMM; NOT native INT4',
            'includes':'vision encoder, language backbone, full denoising, online transforms/scaling',
            'excludes':'simulator, websocket transport; GR00T external observation normalization',
            'warmup':5,'repetitions':30,'action_chunk_per_call':True}
    # Separate instrumented trace: never mix profiler overhead into reported timings.
    macs={'target_linear':0,'all_linear':0}
    from tools.rebuttal.runtime import RebuttalLinear
    def count_macs(mod, inputs, output):
        value=inputs[0].numel()*mod.out_features
        macs['all_linear']+=value
        if isinstance(mod,RebuttalLinear):
            macs['target_linear']+=value
    handles=[m.register_forward_hook(count_macs) for m in model.modules()
             if isinstance(m,(torch.nn.Linear,RebuttalLinear))]
    with torch.profiler.profile(activities=[torch.profiler.ProfilerActivity.CPU,
                                           torch.profiler.ProfilerActivity.CUDA],record_shapes=True) as prof:
        call(0)
    for handle in handles:
        handle.remove()
    result['measured_linear_macs_per_call']=macs
    result['native_int4_macs_per_call']=0
    result['linear_macs_are_not_total_model_flops']=True
    trace=root/job['output'].replace('.json','.trace.json')
    trace.parent.mkdir(parents=True,exist_ok=True)
    prof.export_chrome_trace(str(trace))
    result['operator_summary']=str(prof.key_averages().table(sort_by='self_cuda_time_total',row_limit=30))
    write_json(root/job['output'],result)


def main():
    ap=argparse.ArgumentParser()
    ap.add_argument('--manifest',required=True)
    ap.add_argument('--job',type=int,required=True)
    args=ap.parse_args()
    manifest=json.loads(Path(args.manifest).read_text())
    job=manifest['jobs'][args.job]
    root=Path(manifest['root'])
    done=root/'status'/f'{job["id"]}.done.json'
    if done.exists():
        import hashlib
        previous=json.loads(done.read_text())
        current=hashlib.sha256(Path(args.manifest).read_bytes()).hexdigest()
        if previous.get('manifest_sha256')!=current:
            raise RuntimeError('Completion marker belongs to a different manifest')
        print(f'already complete: {job["id"]}')
        return
    # Strict reproducibility: immutable manifest and source-tree revision.
    import hashlib
    from tools.rebuttal.plan import source_digest
    if source_digest(Path(__file__).resolve().parents[2])!=manifest['source_digest']:
        raise RuntimeError('Source changed since plan generation; generate a new run directory')
    os.environ.setdefault('MUJOCO_GL','egl')
    os.environ.setdefault('PYOPENGL_PLATFORM','egl')
    globals()[job['stage']](job,manifest['paths'],root)
    from tools.rebuttal.core import write_json
    output=root/job['output']
    expected=output/'index.json' if job['stage']=='capture' else output
    if not expected.exists():
        raise RuntimeError(f'Missing expected output: {expected}')
    write_json(done,{'job':job,'output':str(expected),'manifest_sha256':hashlib.sha256(Path(args.manifest).read_bytes()).hexdigest()})

if __name__=='__main__':
    main()
